/**
 * placeModels.js — which 3D model to draw for an endangered place, and
 * which places get one.
 *
 * Generated by tools/make_place_models.py, one model per KIND of place
 * (the same restraint as vesselModels.js: a model claims the kind, not the
 * site — a refinery model is not the Feyzin refinery's layout), standing on
 * a plinth in the call's status colour. Three files per kind because a
 * Cesium model colour tints the whole mesh: {file}.glb (grey, listed
 * without a call), {file}_amber.glb, {file}_red.glb.
 *
 * Drawn by GlobeEndangeredPlacesLayer.jsx when the camera is close
 * (MODEL_MAX_HEIGHT_M), at most MODEL_BUDGET at once; the flat markers
 * stay for everything else.
 */

/** The server's kind (backend/endangered_places.py) → the model's file. */
export const KIND_FILE = {
    refinery: "refinery", fuel_depot: "fuel_depot", fuel_station: "fuel_station",
    gathering: "rally", roundabout: "roundabout", arms_company: "arms_company",
    // other countries' sources (backend/endangered_sources.py): people
    // gathered for a notified assembly, a strike picket or a called action
    // — the rally model says that much and claims no more.
    assembly: "rally", strike: "rally", action: "rally",
}
/** Kinds drawn as their flat marker even close in: an office building in
 *  Brussels is not a factory, and "a site on an activist map" says nothing
 *  about what stands there, so no model can show either honestly. Any kind
 *  in neither list also keeps its marker (modelUrl returns null). */
export const NO_MODEL = ["lobby_office", "listed_site"]
export const FILES = [...new Set(Object.values(KIND_FILE))]
export const STATUSES = ["grey", "amber", "red"]

/** Bumped whenever the models are regenerated (see aircraftModels.js). */
export const MODEL_VERSION = 1

export function modelUrl(kind, alarm = "grey") {
    const f = KIND_FILE[kind]
    if (!f) return null
    const s = STATUSES.includes(alarm) && alarm !== "grey" ? `_${alarm}` : ""
    return `/models/place/${f}${s}.glb?v=${MODEL_VERSION}`
}

/** Models only below this camera height; the markers above it. */
export const MODEL_MAX_HEIGHT_M = 180_000
/** At most this many models at once: each is its own draw call. */
export const MODEL_BUDGET = 150

/**
 * A model's on-screen size. From the top of the 3D range down to a few
 * kilometres, every model is drawn MIN_PX across whatever its kind, so a
 * 30 m rally reads as well as a 130 m tank farm; it never grows past that
 * on screen from afar (minimumPixelSize only enlarges up to MIN_PX). Close
 * in, the nominal metres take over. MAX_SCALE only bounds the enlargement
 * (a 30 m rally is at most 12 km across on the ground, which at the 3D
 * range's top is ~MIN_PX); at 30 it was the cap that bit, and small kinds
 * shrank to 10-pixel dots while depots stayed large.
 */
export const MIN_PX = 56
export const MAX_SCALE = 400

const RANK = { red: 0, amber: 1, grey: 2 }

function distKm(a, b) {
    const r = Math.PI / 180
    const dp = (b.lat - a.lat) * r, dl = (b.lon - a.lon) * r
    const h = Math.sin(dp / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dl / 2) ** 2
    return 12742 * Math.asin(Math.min(1, Math.sqrt(h)))
}

/**
 * Which places are drawn as models: none above maxHeight; below it, the
 * ones inside the view (with a margin) ranked by status — a red call
 * before an amber one before a listed place — then by distance from the
 * view centre, capped at `budget`. Returns a Set of place ids.
 *
 * view: { height, center: {lat, lon}, bounds?: {west, south, east, north} }
 */
export function selectModelPlaces(places, view, { maxHeight = MODEL_MAX_HEIGHT_M, budget = MODEL_BUDGET } = {}) {
    const out = new Set()
    if (!view || !Number.isFinite(view.height) || view.height >= maxHeight || !view.center) return out
    const b = view.bounds
    const padLat = b ? (b.north - b.south) * 0.15 : 0
    const padLon = b ? (b.east - b.west) * 0.15 : 0
    const inView = (p) => !b || (p.lat >= b.south - padLat && p.lat <= b.north + padLat
        && p.lon >= b.west - padLon && p.lon <= b.east + padLon)
    const cand = []
    for (const p of places || []) {
        if (!p || !KIND_FILE[p.kind] || !Number.isFinite(p.lat) || !Number.isFinite(p.lon) || !inView(p)) continue
        cand.push({ id: p.id, r: RANK[p.alarm] ?? 2, d: distKm(view.center, p) })
    }
    cand.sort((a, b2) => a.r - b2.r || a.d - b2.d)
    for (const c of cand.slice(0, budget)) out.add(c.id)
    return out
}

/** A fixed heading per place (radians) from its id, so a row of stations
 *  does not stand in parade order. The site's real layout is not known. */
export function placeHeadingRad(id) {
    let h = 0
    for (const ch of String(id)) h = (h * 31 + ch.charCodeAt(0)) >>> 0
    return ((h % 360) * Math.PI) / 180
}
